mkdir -p cmd/systool internal/sysinfo && cat > cmd/systool/main.go <<'EOF'
// Command systool is a cross-platform CLI that uses OS-level system calls
// not exposed by the Go standard library.
package main

import (
	"fmt"
	"os"

	"github.com/example/systool/internal/sysinfo"
)

func main() {
	info, err := sysinfo.Get()
	if err != nil {
		fmt.Fprintf(os.Stderr, "systool: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("os:      %s\n", info.OS)
	fmt.Printf("release: %s\n", info.Release)
	fmt.Printf("arch:    %s\n", info.Machine)
}
EOF
cat > internal/sysinfo/sysinfo.go <<'EOF'
// Package sysinfo wraps platform-specific system calls behind a common API.
//
// Platform implementations live in files with GOOS suffixes
// (sysinfo_unix.go, sysinfo_windows.go) and use golang.org/x/sys rather
// than the frozen standard-library syscall package.
package sysinfo

// Info describes the running kernel.
type Info struct {
	OS      string
	Release string
	Machine string
}

// Get returns information about the running kernel.
func Get() (Info, error) {
	return get()
}
EOF
cat > internal/sysinfo/sysinfo_unix.go <<'EOF'
//go:build linux || darwin

package sysinfo

import (
	"fmt"

	"golang.org/x/sys/unix"
)

func get() (Info, error) {
	var u unix.Utsname
	if err := unix.Uname(&u); err != nil {
		return Info{}, fmt.Errorf("uname: %w", err)
	}
	return Info{
		OS:      unix.ByteSliceToString(u.Sysname[:]),
		Release: unix.ByteSliceToString(u.Release[:]),
		Machine: unix.ByteSliceToString(u.Machine[:]),
	}, nil
}
EOF
cat > internal/sysinfo/sysinfo_windows.go <<'EOF'
//go:build windows

package sysinfo

import (
	"fmt"

	"golang.org/x/sys/windows"
)

func get() (Info, error) {
	// RtlGetVersion reports the true OS version, unlike GetVersionEx,
	// which lies to processes without a compatibility manifest.
	v := windows.RtlGetVersion()

	var si windows.SystemInfo
	windows.GetNativeSystemInfo(&si)

	return Info{
		OS:      "Windows",
		Release: fmt.Sprintf("%d.%d.%d", v.MajorVersion, v.MinorVersion, v.BuildNumber),
		Machine: archName(si.ProcessorArchitecture),
	}, nil
}

func archName(a uint16) string {
	switch a {
	case windows.PROCESSOR_ARCHITECTURE_AMD64:
		return "x86_64"
	case windows.PROCESSOR_ARCHITECTURE_ARM64:
		return "arm64"
	case windows.PROCESSOR_ARCHITECTURE_INTEL:
		return "x86"
	default:
		return fmt.Sprintf("unknown(%d)", a)
	}
}
EOF
cat > internal/sysinfo/sysinfo_test.go <<'EOF'
